questionvariables.text:
/* Geometrie (fest): Balken liegt bei A auf dem glatten Boden und bei B auf der rauen Kante
   einer Stufe. A = [xA, 0], B = [0, yB] (Kante), Balkenrichtung tAB von A nach B, nAB senkrecht
   zum Balken (nach oben rechts). */
yB: 2;   /* Hoehe der Stufe in der Skizze (in der Aufgabe: b) */
xA: 3;
lAB: sqrt(yB^2+xA^2);
tAB: [-xA, yB];
nAB: [yB, xA];
pA: [xA, 0];
pB: [0, yB];
alphaDeg: float(atan(yB/xA)*180/%pi);
/* Gitterweite a: A, B und die Stufe liegen auf dem Gitter (Stufenhoehe 2a, A im Abstand 3a).
   Balken (Quader) als Polygon: Laenge b = 1.4*|tAB|, Dicke h = 0.2*|nAB|; die Ecke unten
   rechts liegt in A. Schwerpunkt S in der Mitte. b und h sind in der Aufgabe Symbole. */
p1: pA + 1.4*tAB;
p2: pA + 1.4*tAB + 0.2*nAB;
p3: pA + 0.2*nAB;
pS: pA + 0.7*tAB + 0.1*nAB;
/* Momentenbilanz: Lage von B und S relativ zu A, in a (Gitter), b, h und alpha
   (et laengs des Balkens von A nach B, en senkrecht dazu nach oben rechts) */
et: [-cos(alpha), sin(alpha)];
en: [sin(alpha), cos(alpha)];
rB: (pB - pA)*a;
rS: b/2*et + h/2*en;
rSmat: matrix([rS[1]],[rS[2]]);

/* Einheitsvektoren fuer die Musterloesung */
eAB: float(tAB/sqrt(tAB.tAB));
eN: float(nAB/sqrt(nAB.nAB));

/* Skizze */
initdata: [
  ["grid", "", "", -4, 6, -2, 5, 40],
  ["wall", "Boden", [5, 0], [0, 0], 45, "show"],
  ["wall", "Stufe oben", [0, yB], [-3, yB], 45, "show"],
  ["wall", "Stufe rechts", [0, yB], [0, 0], -45, "show"],
  ["polygon", "", pA, p1, p2, p3, "show"],
  ["point", "A", pA],
  ["point", "B", pB,2],
  ["point", "S", pS],
  ["dim", "b", p2, p3, 0.8],
  ["dim", "h", p1, p2, 0.5],
  ["dim", "a", [2, 4], [3, 4], 0],
  ["force", "G", pS, pS - [0, 1.2], 5],
  ["angle", "\\alpha", pA, float(pA + eAB), 0.9, alphaDeg],
  ["description", "\\mu_0", [-1.5, yB], [-2.6, 3]],
  ["description", "\\mu=0", [4.2, 0], [4.9, 0.9]],
  ["contact", "", pA, [0, -1], "Boden", 3],
  ["contact", "", pB, -nAB, ["Stufe oben", "Stufe rechts"], 3],
  ["forceGen", "F", [4.4, 4.2]],
  ["crosshair", "", [5, 2.5], [0, 0], [1, 1], [1, 1], "grid"],
  /* Dummy-Kontakt bei B, damit das graue Kreuz nicht die richtige Orientierung verraet */
  ["contact", "", pB, [0, -1], ["Stufe oben", "Stufe rechts"], 3],
  ["contact", "", pA,  -nAB, "Boden", 3],
  ["dir", "x", [5,0], 0],
  ["dir", "y", [0,2], 90,5,2.5]
];
init: stackjson_stringify(initdata);
i_beam: 5;    /* polygon: der Balken */
i_floor: 2;   /* wall Boden */
i_top: 3;     /* wall Stufe oben */
i_side: 4;    /* wall Stufe rechts */
i_G: 12;      /* weight force */
i_A: 16;      /* contact A */
i_B: 17;      /* contact B */
i_P: 19;      /* crosshair: reference point of the moment balance */

/* Musterloesung: Umgebung deaktiviert, N_A senkrecht zum Boden, N_B senkrecht zum Balken,
   R_B (Haftkraft) laengs des Balkens, hier zur Kante hin; Bezugspunkt A */
refdata: copylist(initdata);
refdata[i_P][3]: pA;
for k in [i_floor, i_top, i_side] do refdata[k][6]: "hide";
refdata: append(refdata, [
  ["force", "N_A", pA - [0, 1.2], pA, 10, "active"],
  ["force", "N_B", float(pB - 1.2*eN), pB, 10, "active"],
  ["force", "R_B", pB, float(pB + 1.2*eAB), 10, "active"]
]);
ref: stackjson_stringify(refdata);

stack_include("https://raw.githubusercontent.com/mkraska/meclib/dev2026/Maxima/dist/fb_value.mac");
stack_include("https://raw.githubusercontent.com/mkraska/meclib/dev2026/Maxima/dist/fb_fbd.mac");

feedbackvariables.text:
obj: fb_objects(objects);
[textA, okA]: fb_contact(obj, names, i_A, "Kontakt A: ", "smooth", ["N_A", "N"]);
[textB, okB]: fb_contact(obj, names, i_B, "Kontakt B: ", "static", ["N_B", "N"], ["R_B", "R", "H", "H_B", "F_H"]);
[txtFBD, okFBD, partsFBD]: fb_fbd(obj, names, [sys = [i_beam], env = [i_floor, i_top, i_side],
                                              supports = [i_A, i_B], reserved = [a, b, h, alpha],
                                              forces = 3, moments = 0]);

obj: fb_objects(objects);
[txt, ok]: fb_EE(S_GGx, sumF(obj, names, [1,0], [contacts = [i_A, i_B]]),
                        [subst = [alpha = atan(yB/xA)], kind = "x"]);

obj: fb_objects(objects);
[txt, ok]: fb_EE(S_GGy, 
  sumF(obj, names, [0,1], [contacts = [i_A, i_B]]),
  [subst = [alpha = atan(yB/xA)], kind = "y"] );

obj: fb_objects(objects);
[txt, ok]: fb_EE(S_GGM, 
  sumM(obj, names, names[i_P], a, [contacts = [i_A, i_B], at = [[i_G, pA*a + rS]]]),
  [subst = [alpha = atan(yB/xA)], kind = "M"]);
